std::vector<espv2::api_proxy::path_matcher::HttpTemplate::Variable> &vars = http_template->Variables();
// Read-only traversal for coverage.
int wildcard_count = 0; for (const auto &v : vars) { if (v.has_wildcard_path) { ++wildcard_count; } }
FUZZ_SET_ATTR_INT(http_template, "vars_size", (int)vars.size());
FUZZ_SET_ATTR_INT(http_template, "vars_wildcards", wildcard_count);
// Validation: We avoid mutating the returned vector to maintain consistency.

