(void)builder->AppendSingleParameterNode();
// Validation: No additional constraints; builder is passed through.

// Access the path parts; reference remains valid for the lifetime of path_info.
const std::vector<std::string> &parts = path_info->path_info();
// Light traversal for coverage.
size_t acc = 0; for (const auto &p : parts) { acc += p.size(); }
FUZZ_SET_ATTR_INT(path_info, "parts_count", (int)parts.size());
// Validation: Read-only accessor; path_info is kept alive by returning it as an output.

// Construct a fresh root node of the trie.
