espv2::api_proxy::path_matcher::PathMatcherLookupResult res = espv2::api_proxy::path_matcher::LookupInPathMatcherNode(*node, parts, http_method);
// Return a heap copy of the result to the pool for downstream checks.
espv2::api_proxy::path_matcher::PathMatcherLookupResult *lookup_result = new espv2::api_proxy::path_matcher::PathMatcherLookupResult(res);
// Validation: Iterators/containers remain valid during the call; node is returned as output and result is materialized on the heap.

