import random
import string
from typing import List, Tuple

# This generator targets fuzzers that expect a single bytes buffer used by
# FUZZ_PARAM_STR (path strings). We craft valid and interesting URL path
# strings that, when split on '/', exercise different code paths:
# - Literal segments, numeric, unicode, percent-enc, dots
# - Wildcard-like tokens ("*", "**", ".") as literal parts
# - Custom verbs suffix (":verb") and common HTTP method-like tokens inside
# - Variable-looking parts that HttpTemplate might parse against
# - Empty and root-only, leading/trailing/multiple slashes (splitter collapses
#   them so we place empty vs non-empty segments deliberately)
# - Long segments and varying segment counts, within 4096 bytes
# The fuzzer stub splits on '/' without query handling, but the library often
# strips queries; we include both with and without '?'.

MAX_SIZE = 4096

LITERALS = [
    "a", "b", "c", "users", "projects", "v1", "v2", "items",
    "get", "list", "update", "delete", "123", "42", "0",
    "..", ".", "-", "_", "~", "%2F", "%2f", "%7B", "%7D",
    "ä", "ñ", "тест", "漢字",
]

WILDCARDISH = ["*", "**", "."]

CUSTOM_VERBS = [":run", ":batchGet", ":custom", ":upload", ":download"]

QUERY_SAMPLES = [
    "", "?x=1", "?a=b&c=d", "?q=abc%2Fdef", "?empty=", "?flag"
]

# Variable-like field paths commonly seen in templates (as literals here)
FIELDISH = [
    "name", "parent", "id", "resource", "book", "shelf", "userId",
    "foo.bar", "foo_bar", "x.y.z"
]

SAFE_CHARS = string.ascii_letters + string.digits + "-_.~"


def _rand(rng: random.Random, seq):
    return seq[rng.randrange(len(seq))]


def rand_segment(rng: random.Random) -> str:
    choice = rng.random()
    if choice < 0.15:
        # long alnum
        n = rng.randint(8, 48)
        return ''.join(rng.choice(SAFE_CHARS) for _ in range(n))
    if choice < 0.30:
        # numeric
        return str(rng.randint(0, 10**9))
    if choice < 0.45:
        return _rand(rng, LITERALS)
    if choice < 0.55:
        return _rand(rng, FIELDISH)
    if choice < 0.65:
        # percent-encoded style
        n = rng.randint(1, 5)
        parts = []
        for _ in range(n):
            parts.append("%" + ''.join(rng.choice("0123456789ABCDEF") for _ in range(2)))
        return ''.join(parts)
    if choice < 0.75:
        # unicode mix
        uni = ["ä", "ø", "ß", "ñ", "é", "漢", "字", "테", "스트"]
        n = rng.randint(1, 4)
        return ''.join(rng.choice(uni) for _ in range(n))
    if choice < 0.85:
        return _rand(rng, WILDCARDISH)
    # dotted segments resembling extensions or field paths
    parts = [ ''.join(rng.choice(string.ascii_lowercase) for _ in range(rng.randint(1,4))) for _ in range(rng.randint(2,4)) ]
    return '.'.join(parts)


def build_path(rng: random.Random) -> str:
    # Decide overall pattern to hit different logic in consumers
    mode = rng.randrange(0, 10)

    if mode == 0:
        # root
        base = "/"
    elif mode == 1:
        # empty (no parts)
        base = ""
    elif mode == 2:
        # single segment
        base = "/" + rand_segment(rng)
    elif mode == 3:
        # multi segments with potential custom verb suffix
        count = rng.randint(2, 6)
        segs = [rand_segment(rng) for _ in range(count)]
        if rng.random() < 0.5:
            segs[-1] = segs[-1] + _rand(rng, CUSTOM_VERBS)
        base = "/" + "/".join(segs)
    elif mode == 4:
        # include redundant slashes (splitter collapses to drop empties)
        segs = [rand_segment(rng) for _ in range(rng.randint(2, 5))]
        base = "/" + "/".join(segs)
        # randomly inject duplicate slashes
        inserts = rng.randint(1, 3)
        for _ in range(inserts):
            pos = rng.randint(1, len(base)-1)
            base = base[:pos] + "/" + base[pos:]
    elif mode == 5:
        # trailing slash
        segs = [rand_segment(rng) for _ in range(rng.randint(1, 5))]
        base = "/" + "/".join(segs) + "/"
    elif mode == 6:
        # mixture including wildcard-like tokens as literal parts
        segs = []
        for _ in range(rng.randint(3, 7)):
            if rng.random() < 0.3:
                segs.append(_rand(rng, WILDCARDISH))
            else:
                segs.append(rand_segment(rng))
        base = "/" + "/".join(segs)
    elif mode == 7:
        # dot and dotdot as segments
        segs = [".", ".."] + [rand_segment(rng) for _ in range(rng.randint(1,3))]
        base = "/" + "/".join(segs)
    elif mode == 8:
        # long-ish path near limit
        segs = []
        while True:
            seg = rand_segment(rng)
            if not seg:
                continue
            candidate = ("/" if not segs else "/".join(["" ] + segs + [seg]))
            if len(candidate) > MAX_SIZE - 32:
                break
            segs.append(seg)
        base = "/" + "/".join(segs)
    else:
        # include query string tail
        segs = [rand_segment(rng) for _ in range(rng.randint(1, 5))]
        base = "/" + "/".join(segs) + _rand(rng, QUERY_SAMPLES)

    # Occasionally prepend without leading slash (relative path)
    if rng.random() < 0.2 and base.startswith("/"):
        base = base[1:]

    # Ensure final size cap
    if len(base.encode('utf-8')) > MAX_SIZE:
        base = base.encode('utf-8')[:MAX_SIZE].decode('utf-8', errors='ignore')

    return base


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    path = build_path(rng)
    # Return as bytes; the fuzzer infra will feed it to FUZZ_PARAM_STR
    return path.encode('utf-8')

import random
import string
from typing import List

def _rand_choice(rng: random.Random, seq):
    return seq[rng.randrange(len(seq))]

COMMON_METHODS = [b"GET", b"POST", b"PUT", b"PATCH", b"DELETE", b"HEAD", b"OPTIONS"]
CUSTOM_VERBS = [b":audit", b":search", b":download"]

# Build realistic path strings that exercise ExtractRequestParts and manual split logic.
# We generate a mix of:
# - simple literal paths
# - paths with numeric and hex-like ids
# - paths with custom verbs (both in and out of advertised set)
# - paths with redundant slashes
# - paths with query strings and fragments
# - empty/root and trailing slash cases
# - segments that look like wildcards or parameters to populate trie keys in other components
SEG_LITERALS = [
    b"users", b"projects", b"v1", b"v2", b"items", b"orders", b"files",
    b"metadata", b"config", b"status", b"logs", b"search", b"download",
]

PARAM_LIKE = [b"-", b"_", b".", b"%2E", b"*", b"**", b"-.", b"..", b"--", b"id"]

HEX_CHARS = b"0123456789abcdef"
ALNUM = string.ascii_letters.encode() + b"0123456789-_"

def _rand_hex_bytes(rng: random.Random, n: int) -> bytes:
    # Build a bytes object of hex characters using integer to bytes conversion
    return bytes(HEX_CHARS[rng.randrange(len(HEX_CHARS))] for _ in range(n))

def _rand_id(rng: random.Random) -> bytes:
    t = rng.randrange(4)
    if t == 0:
        # decimal id
        return str(rng.randrange(0, 10**9)).encode()
    if t == 1:
        # hex-ish
        n = rng.randrange(4, 16)
        return _rand_hex_bytes(rng, n)
    if t == 2:
        # uuid-like (not strict)
        parts = [8, 4, 4, 4, 12]
        return b"-".join(_rand_hex_bytes(rng, k) for k in parts)
    # mixed
    n = rng.randrange(3, 20)
    return bytes(ALNUM[rng.randrange(len(ALNUM))] for _ in range(n))

def _maybe_query(rng: random.Random) -> bytes:
    if rng.random() < 0.6:
        pairs = []
        for _ in range(rng.randrange(1, 4)):
            k = _rand_id(rng)
            v = _rand_id(rng)
            pairs.append(k + b"=" + v)
        q = b"?" + b"&".join(pairs)
        if rng.random() < 0.2:
            q += b"#frag"
        return q
    return b""

def _build_segments(rng: random.Random) -> List[bytes]:
    segs: List[bytes] = []
    n = rng.randrange(0, 6)  # 0 -> root
    for _ in range(n):
        choice = rng.randrange(6)
        if choice == 0:
            segs.append(_rand_choice(rng, SEG_LITERALS))
        elif choice == 1:
            segs.append(_rand_id(rng))
        elif choice == 2:
            segs.append(_rand_choice(rng, PARAM_LIKE))
        elif choice == 3:
            segs.append(b"." + _rand_id(rng))
        elif choice == 4:
            segs.append(b"~" + _rand_id(rng))
        else:
            # mixture
            segs.append(_rand_choice(rng, SEG_LITERALS) + b"-" + _rand_id(rng))
    return segs

def _insert_redundant_slashes(rng: random.Random, path: bytes) -> bytes:
    if not path:
        return path
    if rng.random() < 0.5:
        path = b"/" + path
    if rng.random() < 0.4:
        path += b"/"
    if rng.random() < 0.5:
        # replace limited number of slashes with double slashes
        count = rng.randrange(1, 4)
        for _ in range(count):
            path = path.replace(b"/", b"//", 1)
    return path

def _maybe_custom_verb(rng: random.Random) -> bytes:
    if rng.random() < 0.5:
        # sometimes choose one from known set, sometimes random to test unknown verbs
        if rng.random() < 0.7:
            return _rand_choice(rng, CUSTOM_VERBS)
        else:
            return b":" + _rand_id(rng)
    return b""

def _build_path_string(rng: random.Random) -> bytes:
    # Special cases to hit edge handling
    special = rng.random()
    if special < 0.08:
        return b"/"  # root
    if special < 0.16:
        return b""  # empty input
    if special < 0.24:
        return b"///////"  # many slashes

    segs = _build_segments(rng)
    path = b"/".join(segs)
    path = _insert_redundant_slashes(rng, path)

    # Optionally append custom verb
    if segs:
        verb = _maybe_custom_verb(rng)
        if verb:
            path = path.rstrip(b"/") + verb

    # Optionally add query
    path += _maybe_query(rng)
    return path[:4096]

# The fuzzing harness selects one string via FUZZ_PARAM_STR for both stubs.
# We return a buffer that concatenates multiple interesting path strings and
# also an HTTP method token so the pool has realistic data to pick from.
# The harness pulls data sequentially from the provided bytes.

def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    blobs: List[bytes] = []

    # Prepend a valid HTTP method token to improve method selection elsewhere
    method = _rand_choice(rng, COMMON_METHODS)
    blobs.append(method + b"\n")

    # Provide a mix of paths that the stubs will split/extract
    count = rng.randrange(5, 12)
    for _ in range(count):
        blobs.append(_build_path_string(rng) + b"\n")

    # Include some paths explicitly covering custom verbs
    for v in CUSTOM_VERBS:
        # with and without query
        base = b"/" + _rand_choice(rng, SEG_LITERALS) + b"/" + _rand_id(rng)
        blobs.append(base + v + b"\n")
        blobs.append(base + v + _maybe_query(rng) + b"\n")

    out = b"".join(blobs)
    return out[:4096]

import random
import string
from typing import List, Tuple

# Target format: URL path with optional query, may contain redundant slashes and custom verb suffixes
# Custom verbs candidates used by fuzzers
VERBS = [":audit", ":search", ":download", ":lock", ":custom"]
METHODS = ["GET","POST","PUT","PATCH","DELETE","HEAD","OPTIONS"]

# Build a variety of path segments: literals, numeric, hex, unicode-ish, dots, wildcard-like tokens
LITERAL_SEGMENTS = [
    "books", "authors", "v1", "v2", "users", "profile", "items", "orders",
    "a", "b", "c", "x", "y", "z", "123", "00", "deadbeef", "ä", "β", ".", "..",
    "-", "_", "~", "%25", "name%2Fwith%2Fslash", "space%20here"
]

QUERY_KEYS = [
    "page", "limit", "offset", "q", "filter", "sort", "fields", "pretty",
    "download", "verbose", "redirect", "empty"
]
QUERY_VALUES = [
    "1", "2", "10", "true", "false", "name", "title", "new", "old",
    "abc%2Fdef", "ä", "", "null", "0"
]

def rand_choice(rng: random.Random, seq: List[str]) -> str:
    return seq[rng.randrange(len(seq))]

def random_segment(rng: random.Random) -> str:
    t = rng.randrange(8)
    if t == 0:
        # random ascii word
        length = rng.randint(1, 12)
        alphabet = string.ascii_letters + string.digits + "-_~.%"
        return ''.join(rng.choice(alphabet) for _ in range(length))
    elif t == 1:
        return rand_choice(rng, LITERAL_SEGMENTS)
    elif t == 2:
        # numeric
        return str(rng.randint(0, 999999))
    elif t == 3:
        # percent-encoded slash-like content (tests collapsing and verb recognition)
        return "name%2Fwith%2Fslash"
    elif t == 4:
        # dot segments (edge handling by extractor)
        return rand_choice(rng, [".", ".."])
    elif t == 5:
        # empty segment expressed later by inserting extra slashes; here return literal likely to stay
        return ""
    elif t == 6:
        # unicode-ish
        return rand_choice(rng, ["café", "π", "файл", "テスト", "δοκιμή"])
    else:
        # path parameter-like text
        return rand_choice(rng, ["id", "name", "*", "**", ".", "-", "_hidden"]) 

def maybe_custom_verb(rng: random.Random) -> str:
    if rng.random() < 0.5:
        return ""
    return rand_choice(rng, VERBS)

def build_path(rng: random.Random) -> str:
    # Decide base style
    style = rng.randrange(6)
    parts: List[str] = []

    if style == 0:
        # Root
        parts = []
    elif style == 1:
        # Short path 1-3 segments
        n = rng.randint(1, 3)
        parts = [random_segment(rng) for _ in range(n)]
    elif style == 2:
        # Medium path 3-6 segments with some empties to make //
        n = rng.randint(3, 6)
        parts = []
        for _ in range(n):
            s = random_segment(rng)
            if rng.random() < 0.25:
                parts.append("")  # force redundant slash
            parts.append(s)
    elif style == 3:
        # Versioned API path
        parts = [rand_choice(rng, ["v1", "v2", "v1beta1"]) , rand_choice(rng, ["projects","books","users"])]
        if rng.random() < 0.7:
            parts.append(str(rng.randint(1, 9999)))
        if rng.random() < 0.5:
            parts.append(rand_choice(rng, ["topics","shelves","profiles"]))
    elif style == 4:
        # Trailing slash variations
        n = rng.randint(1, 5)
        parts = [random_segment(rng) for _ in range(n)]
        # Represent extra trailing slashes by adding empty tail markers later
        if rng.random() < 0.7:
            parts.append("")
            if rng.random() < 0.3:
                parts.append("")
    else:
        # Include dot segments and encoded items
        parts = [".", "..", rand_choice(rng, ["a","b","c"]) , "abc%2Fdef"]
        if rng.random() < 0.5:
            parts.append("..")

    # Assemble with slashes, keeping empty parts to yield //
    base = "/" + "/".join(parts)
    # Possibly collapse or expand with leading slashes
    if rng.random() < 0.2:
        base = "/" * rng.randint(1, 3) + base.lstrip("/")

    # Append custom verb sometimes
    verb = maybe_custom_verb(rng)
    if verb:
        base = base.rstrip("/") + verb

    # Optionally add query string with 0-5 pairs and noise
    if rng.random() < 0.8:
        qcount = rng.randint(0, 5)
        if qcount > 0 or rng.random() < 0.2:
            qs = []
            for _ in range(qcount):
                k = rand_choice(rng, QUERY_KEYS)
                v = rand_choice(rng, QUERY_VALUES)
                if rng.random() < 0.2:
                    # repeated key
                    k = k
                if rng.random() < 0.2:
                    # no value
                    qs.append(k)
                else:
                    qs.append(f"{k}={v}")
            # Add fragments or stray separators occasionally
            if rng.random() < 0.2:
                qs.append("")
            base += "?" + "&".join(qs)
            if rng.random() < 0.15:
                base += "#fragment"
    return base


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Produce between 1 and 3 plausible request lines concatenated with newlines,
    # so a consumer picking FUZZ_PARAM_STR may take any slice; primary use expects one path.
    count = rng.randint(1, 2)
    paths = [build_path(rng) for _ in range(count)]
    data = "\n".join(paths)
    b = data.encode("utf-8", errors="surrogatepass")
    if len(b) > 4096:
        b = b[:4096]
    return b
